'use strict';

// MODULES //

var spawn = require( 'child_process' ).spawn;
var path = require( 'path' );
var logger = require( 'debug' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var ENV = require( '@stdlib/process/env' );
var copy = require( '@stdlib/utils/copy' );
var merge = require( '@stdlib/utils/merge' );
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var createServer = require( '@stdlib/plot/base/server' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var debug = logger( 'plot:view:electron:main' );
var electron = tryRequire( '@stdlib/electron' );

var FOPTS = {
	'encoding': 'utf8'
};
var INDEX_HTML = readFileSync( path.join( __dirname, 'index.html' ), FOPTS );


// MAIN //

/**
* Renders a plot in an Electron window.
*
* @private
* @param {Object} plot - plot instance
* @param {NonNegativeInteger} plot.width - plot width
* @param {NonNegativeInteger} plot.height - plot height
* @param {Array<string>} plot.title - plot title
* @param {Function} plot.render - method for rendering a plot instance
* @throws {Error} Electron must be properly installed
*/
function view( plot ) {
	var server;
	var json;
	var ctx;

	if ( instanceOf( electron, Error ) ) {
		throw new Error( 'invalid operation. Unable to load Electron. Ensure Electron is installed and try again.' );
	}
	// Cache various properties in order to avoid mutation during asynchronous rendering...
	ctx = {
		'width': plot.width,
		'height': plot.height,
		'title': '' // plot.title.text.join( '\n' ) // FIXME
	};

	// Cache the current chart state by serializing to JSON:
	json = plot.toJSON(); /* eslint-disable-line no-unused-vars */ // FIXME: remove once used

	debug( 'Creating a server...' );
	createServer( router, onReady );

	/**
	* Callback invoked once a server is ready to receive requests.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @param {Server} _server - server instance
	* @throws {Error} unexpected error
	*/
	function onReady( error, _server ) {
		var child;
		var addr;
		var opts;
		var env;

		if ( error ) {
			throw error;
		}
		server = _server;

		addr = server.address();
		debug( 'Server initialized. Server is listening for requests on %s:%d.', addr.address, addr.port );

		debug( 'Electron executable: %s.', electron );

		// TODO: extract fixed env vars to config file and then won't need to pass via environment variables, but can simply require
		env = {
			'SERVER_PORT': addr.port,
			'SERVER_ADDRESS': addr.address,
			'PLOT_WIDTH': ctx.width,
			'PLOT_HEIGHT': ctx.height,
			'PLOT_APP_PATH': __dirname,
			'PLOT_TITLE': ctx.title || 'stdlib'
		};
		debug( 'Electron process environment variables: %s.', JSON.stringify( env ) );

		opts = {
			'cwd': __dirname,
			'detached': true,
			'stdio': 'ignore' // NOTE: when debugging, set to 'inherit'
		};
		debug( 'Electron process options: %s.', JSON.stringify( opts ) );

		// Merge the current process' environment variables:
		opts.env = merge( {}, copy( ENV ), env );

		debug( 'Spawning an Electron process...' );
		child = spawn( electron, [ './main.js' ], opts );
		child.unref();
	}

	/**
	* Request handler.
	*
	* @private
	* @param {IncomingMessage} request - HTTP request object
	* @param {ServerResponse} response - HTTP response object
	* @returns {void}
	*/
	function router( request, response ) {
		var url;

		url = request.url;
		debug( 'Received a request for %s', url );

		if ( url === '/index.html' ) {
			response.write( INDEX_HTML );
			response.end();
			return;
		}
		if ( url === '/close' ) {
			// FIXME: this is temporary
			response.once( 'finish', onFinish );
			response.write( 'OK' );
			response.end();
			return;
		}
		debug( 'TODO: fix me' );
	}

	/**
	* Callback invoked once the server should close.
	*
	* @private
	*/
	function onFinish() {
		debug( 'Finished serving content.' );
		debug( 'Closing the server...' );
		server.close();
	}
}


// EXPORTS //

module.exports = view;
